package com.eventhub.dto; import com.eventhub.entity.AuditLog; import java.time.Instant; public record AuditLogResponse(Long id,Long userId,String action,String entityType,Long entityId,String ipAddress,Instant timestamp,String details){public static AuditLogResponse from(AuditLog a){return new AuditLogResponse(a.getId(),a.getUserId(),a.getAction(),a.getEntityType(),a.getEntityId(),a.getIpAddress(),a.getTimestamp(),a.getDetails());}}
